// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetDesk Desk terms
	// (GET /desk)
	GetDesk(ctx context.Context, request GetDeskRequestObject) (GetDeskResponseObject, error)
	// AcceptQuote Accept an open quote; the trade settles once the taker's allocations land
	// (POST /quotes/{id}/accept)
	AcceptQuote(ctx context.Context, request AcceptQuoteRequestObject) (AcceptQuoteResponseObject, error)
	// CreateRfq Ask makers for quotes
	// (POST /rfqs)
	CreateRfq(ctx context.Context, request CreateRfqRequestObject) (CreateRfqResponseObject, error)
	// ListRfqHistory The caller's RFQs that closed without a trade
	// (GET /rfqs/history)
	ListRfqHistory(ctx context.Context, request ListRfqHistoryRequestObject) (ListRfqHistoryResponseObject, error)
	// ListIncomingRfqs RFQs the caller was asked to quote (open ones and those closed in the last hour)
	// (GET /rfqs/incoming)
	ListIncomingRfqs(ctx context.Context, request ListIncomingRfqsRequestObject) (ListIncomingRfqsResponseObject, error)
	// ListMyRfqs The caller's RFQs with their quotes (open ones and those closed in the last hour)
	// (GET /rfqs/mine)
	ListMyRfqs(ctx context.Context, request ListMyRfqsRequestObject) (ListMyRfqsResponseObject, error)
	// CancelRfq Cancel an open RFQ (not while a trade on it is settling)
	// (DELETE /rfqs/{id})
	CancelRfq(ctx context.Context, request CancelRfqRequestObject) (CancelRfqResponseObject, error)
	// SubmitQuote Quote an RFQ; the quote commits the maker's funds on the ledger
	// (POST /rfqs/{id}/quotes)
	SubmitQuote(ctx context.Context, request SubmitQuoteRequestObject) (SubmitQuoteResponseObject, error)
	// ListTrades Trades of the caller in either role
	// (GET /trades)
	ListTrades(ctx context.Context, request ListTradesRequestObject) (ListTradesResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// GetDesk operation middleware
func (sh *strictHandler) GetDesk(w http.ResponseWriter, r *http.Request) {
	var request GetDeskRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.GetDesk(ctx, request.(GetDeskRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "GetDesk")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(GetDeskResponseObject); ok {
		if err := validResponse.VisitGetDeskResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

